logic:
// Avoid duplicating the chip
if (element.querySelector('#ext-shorts-only-chip')) return;

// Build a chip that visually matches the existing inactive chips
const chip = document.createElement('yt-chip-cloud-chip-renderer');
chip.id = 'ext-shorts-only-chip';
chip.setAttribute('chip-style', 'STYLE_HOME_FILTER');
chip.className = 'style-scope yt-chip-cloud-renderer';

chip.innerHTML = `
  <div id="chip-shape-container" class="style-scope yt-chip-cloud-chip-renderer">
    <chip-shape class="ytChipShapeHost">
      <button class="ytChipShapeButtonReset" role="tab" aria-selected="false" id="ext-shorts-only-btn"
              style="cursor:pointer;">
        <div class="ytChipShapeChip ytChipShapeInactive ytChipShapeOnlyTextPadding"
             id="ext-shorts-only-inner">
          <div>Shorts only</div>
          <yt-touch-feedback-shape aria-hidden="true"
            class="ytSpecTouchFeedbackShapeHost ytSpecTouchFeedbackShapeTouchResponse">
          </yt-touch-feedback-shape>
        </div>
      </button>
    </chip-shape>
  </div>`;

// Insert after the second chip (Unwatched = index 1)
const chips = element.querySelectorAll('yt-chip-cloud-chip-renderer');
if (chips.length >= 2) {
  chips[1].insertAdjacentElement('afterend', chip);
} else {
  element.appendChild(chip);
}

// Toggle logic
const btn = chip.querySelector('#ext-shorts-only-btn');
const innerDiv = chip.querySelector('#ext-shorts-only-inner');

btn.addEventListener('click', function() {
  const isActive = btn.getAttribute('aria-selected') === 'true';

  if (isActive) {
    // Deactivate: restore all content
    btn.setAttribute('aria-selected', 'false');
    innerDiv.classList.remove('ytChipShapeActive');
    innerDiv.classList.add('ytChipShapeInactive');

    document.querySelectorAll('.ext-hidden-by-shorts-chip').forEach(function(el) {
      el.style.display = '';
      el.classList.remove('ext-hidden-by-shorts-chip');
    });
  } else {
    // Activate: hide everything in the results that is NOT a Shorts shelf
    btn.setAttribute('aria-selected', 'true');
    innerDiv.classList.remove('ytChipShapeInactive');
    innerDiv.classList.add('ytChipShapeActive');

    // Deselect any native active chip
    document.querySelectorAll('yt-chip-cloud-chip-renderer.iron-selected').forEach(function(c) {
      const b = c.querySelector('button[role="tab"]');
      const d = c.querySelector('.ytChipShapeChip');
      if (b) b.setAttribute('aria-selected', 'false');
      if (d) { d.classList.remove('ytChipShapeActive'); d.classList.add('ytChipShapeInactive'); }
    });

    // Hide all non-Shorts items inside the results section
    const contentsEl = document.querySelector('#contents.ytd-item-section-renderer');
    if (!contentsEl) return;

    Array.from(contentsEl.children).forEach(function(child) {
      // Check if this is a Shorts grid-shelf
      const isShortShelf = child.tagName.toLowerCase() === 'grid-shelf-view-model' &&
        child.querySelector('.shortsLockupViewModelHost');
      if (!isShortShelf) {
        child.style.display = 'none';
        child.classList.add('ext-hidden-by-shorts-chip');
      }
    });
  }
});

// Find all grid-shelf-view-model elements that are labelled "Shorts"
// (the canonical "Shorts" shelf, not the named playlist shelves)
const shelves = element.querySelectorAll('grid-shelf-view-model');
let shortsShelves = [];

shelves.forEach(function(shelf) {
  const header = shelf.querySelector('.ytShelfHeaderLayoutTitle');
  if (!header) return;
  const text = header.textContent.trim();
  // Match exactly "Shorts" (not "Cute Cat Compilations✨" etc.)
  if (text === 'Shorts') {
    shortsShelves.push(shelf);
  }
});

if (shortsShelves.length === 0) return;

// Check if already at top (first direct child)
const firstChild = element.firstElementChild;
if (firstChild && shortsShelves.includes(firstChild)) return;

// Move each Shorts shelf to the very top, preserving their relative order
// We prepend in reverse so their order is maintained
for (let i = shortsShelves.length - 1; i >= 0; i--) {
  element.prepend(shortsShelves[i]);
}
